"""Fixture records."""


class Fixture:
    def __init__(self, club, goals):
        self.club = club
        self.goals = goals

    def __repr__(self):
        return "Fixture(%r, %r)" % (self.club, self.goals)


ROWS = [('united', 13), ('united', 25), ('rovers', 18), ('united', 38), ('united', 55), ('united', 32)]


def load_fixtures():
    """Yield the stored fixtures one at a time."""
    for club, goals in ROWS:
        yield Fixture(club, goals)
